import csv
# Check for extended times (>24:00:00)
with open('inputs/gtfs/gtfs_extracted/stop_times.txt', 'r') as f:
    reader = csv.DictReader(f)
    for i, row in enumerate(reader):
        for col in ['arrival_time', 'departure_time']:
            t = row[col]
            if t:
                parts = t.split(':')
                if len(parts) == 3:
                    h = int(parts[0])
                    if h > 24:
                        print(f'Extended time found: {t} in row {i+1}')
                        break
        if i > 100:
            break
print('Done checking')
""}

