{"command":"python3 -c "
import csv
# Check ALL rows for extended times
with open('inputs/gtfs/gtfs_extracted/stop_times.txt', 'r') as f:
    reader = csv.DictReader(f)
    extended = []
    for i, row in enumerate(reader):
        for col in ['arrival_time', 'departure_time']:
            t = row[col]
            if t:
                parts = t.split(':')
                if len(parts) == 3:
                    h = int(parts[0])
                    if h > 24:
                        extended.append(t)
    print(f'Extended times found: {len(extended)}')
    for t in extended[:10]:
        print(f'  {t}')
print('Done')
""}

